parameters.jsCode:
const input = $input.first().json;
const execution = input.execution ?? {};
return [{
  json: {
    workflow: input.workflow?.name ?? 'Workflow inconnu',
    workflowId: input.workflow?.id ?? '',
    failedNode: execution.lastNodeExecuted ?? 'Inconnu',
    message: execution.error?.message ?? 'Erreur sans message',
    executionUrl: execution.url ?? '',
    executionId: execution.id ?? '',
    timestamp: new Date().toISOString(),
  },
}];

